        {
            if (string.IsNullOrEmpty(value)) return value;
            if (IsEncrypted(value))
            {
                return decrypt(value, CryptPurpose.a, CryptPrefix.d) ?? value;
            }
            
            // No TDM Portal Connection Profile, senhas podem vir sem o prefixo {cry}
            // (ex: "BdXneRBJbFTXwag2ivDci3zf6V65dpGNDyZ3WLcqN6-k1xzdFHIAszqN3lx0I+jwM52v")
            try
            {
                string decrypted = decrypt(value, CryptPurpose.a, CryptPrefix.a);
                if (!string.IsNullOrWhiteSpace(decrypted))
                {
                    return decrypted;
                }
            }
            catch { }

            return value;
        }
    }
